var bytes = require('..');

describe('proof', function () {
  it('parses multi-digit numbers with units', function () {
    assert.strictEqual(bytes('1024kb'), 1024 * 1024);
    assert.strictEqual(bytes('10mb'), 10 * 1024 * 1024);
    assert.strictEqual(bytes('512kb'), 512 * 1024);
    assert.strictEqual(bytes('123gb'), 123 * Math.pow(1024, 3));
    assert.strictEqual(bytes('12.5kb'), Math.floor(12.5 * 1024));
