});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('defaults to 2 decimal places when options are passed without decimalPlaces', function () {
    // fractional value in KB: 1536 bytes = 1.5KB
    assert.strictEqual(bytes(1536, { unitSeparator: ' ' }), '1.5 KB');
    // fixedDecimals must still yield the default 2 decimals
    assert.strictEqual(bytes(1024, { fixedDecimals: true }), '1.00KB');
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Core schema: an explicit !!int tag must accept signed binary integers
    // ([-+]?0b[0-1]+). The patch changed the prefix to [^-+]?, which rejects
    // signed binary and instead admits junk like "10b1010".
    assert.strictEqual(load('!!int -0b1010'), -10);
    assert.strictEqual(load('!!int +0b101'), 5);
    // parseInt("10b1010", 10) stops at "b", so under the broken pattern this
    // garbage resolves to 10 instead of being rejected.
    assert.throws(() => load('!!int 10b1010'));
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // YAML 1.2 core schema: an explicitly tagged unsigned octal literal is a valid int
    assert.strictEqual(load('!!int 0o777'), 511);
    assert.strictEqual(load('!!int 0o10'), 8);
    // signed octal and the other bases must keep working
    assert.strictEqual(load('!!int +0o17'), 15);
    assert.strictEqual(load('!!int -0o17'), -15);
    assert.strictEqual(load('!!int 0b101'), 5);
    assert.strictEqual(load('!!int 0xFF'), 255);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('rejects non-string values instead of coercing them', function () {
    // null/undefined must produce the documented validation error,
    // not a TypeError from reading .length on null
    assert.throws(function () {
      ms(null);
    }, /val is not a non-empty string or a valid number/);

    // arrays have a length > 0 but are not strings; they must be rejected
    // rather than parsed via String() coercion
    assert.throws(function () {
      ms(['2 days']);
    }, /val is not a non-empty string or a valid number/);

    // objects with a length property must be rejected as well
    assert.throws(function () {
      ms({ length: 2 });
    }, /val is not a non-empty string or a valid number/);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('pluralizes when the input is exactly 1.5 units', function () {
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
    assert.strictEqual(ms(47336400000, { long: true }), '2 years');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('throws the documented error message for an invalid string', function () {
    assert.throws(function () {
      ms('banana');
    }, function (err) {
      return err instanceof Error &&
        err.message === 'val is not a non-empty string or a valid number. val="banana"';
    });
  });

  it('throws the documented error message for undefined input', function () {
    assert.throws(function () {
      ms(undefined);
    }, function (err) {
      return err instanceof Error &&
        err.message === 'val is not a non-empty string or a valid number. val=undefined';
    });
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('keeps the 100-char parse guard for long strings', function () {
    // 101 digits: longer than the guard limit, and it matches the parse regex
    var long = new Array(102).join('1');
    assert.strictEqual(ms(long), undefined);

    // long but otherwise well-formed duration string
    var dur = new Array(101).join('9') + ' days';
    assert.strictEqual(ms(dur), undefined);
  });
});

